(()=>{"use strict";const logo="./iSchool-logo-colors-20260730.svg?v=20260730-3";function apply(){document.querySelectorAll('#qa-login-logo img,aside img[alt*="iSchool"],#qae-panel img[alt*="iSchool"],#qae-v3 img[alt*="iSchool"]').forEach(img=>{if(img.getAttribute("src")!==logo)img.setAttribute("src",logo)});const aside=document.querySelector("aside"),row=aside?.querySelector(".border-b .flex.items-center.gap-3");if(row&&!row.querySelector(".qae-logo")){const old=row.firstElementChild;if(old){const box=document.createElement("div");box.className="qae-logo";box.style.cssText="display:flex;width:150px;height:58px;padding:8px 10px;align-items:center;justify-content:center;border-radius:12px;background:#fff";box.innerHTML=`<img src="${logo}" alt="iSchool logo" style="display:block;width:100%;height:auto">`;old.replaceWith(box)}}}new MutationObserver(apply).observe(document.documentElement,{childList:true,subtree:true});document.readyState==="loading"?document.addEventListener("DOMContentLoaded",apply,{once:true}):apply();setInterval(apply,1200)})();